 const [event,setEvent]=useState(null),[organizations,setOrganizations]=useState([]),[selectedOrganization,setSelectedOrganization]=useState(''),[organizationSearch,setOrganizationSearch]=useState(''),[organizationMenuOpen,setOrganizationMenuOpen]=useState(false),[identityForm,setIdentityForm]=useState({full_name:''}),[loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[error,setError]=useState('');
 useEffect(()=>{let active=true;supabase.functions.invoke('public-event-directory',{body:{slug}}).then(({data,error})=>{if(!active)return;if(error||data?.error)setError(data?.error||error.message);else{setEvent(data.event);setOrganizations(data.organizations||[])}setLoading(false)}).catch(e=>{if(active){setError(e.message||'Gagal memuat event');setLoading(false)}});return()=>{active=false}},[slug]);
