function PublicRundownPreview({slug}){
 const [event,setEvent]=useState(null),[agendas,setAgendas]=useState([]),[loading,setLoading]=useState(true),[error,setError]=useState(''),[now,setNow]=useState(Date.now());
 useEffect(()=>{const timer=setInterval(()=>setNow(Date.now()),1000);return()=>clearInterval(timer)},[]);
 useEffect(()=>{let active=true;async function load(){setLoading(true);setError('');try{const{data,error:invokeError}=await supabase.functions.invoke('public-event-directory',{body:{slug}});if(invokeError||data?.error)throw new Error(data?.error||invokeError.message||'Event tidak ditemukan');if(!data?.event?.id)throw new Error('Event tidak ditemukan');if(!active)return;setEvent(data.event);const{data:agendaData,error:agendaError}=await supabase.from('event_agendas').select('id,title,starts_at,ends_at,person_in_charge,description,sort_order').eq('event_id',data.event.id).order('starts_at');if(agendaError)throw agendaError;if(active)setAgendas(agendaData||[])}catch(e){if(active)setError(e.message||'Gagal memuat rundown')}finally{if(active)setLoading(false)}}load();return()=>{active=false}},[slug]);
 const clock=new Intl.DateTimeFormat('id-ID',{hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23',timeZone:'Asia/Jakarta'}).format(new Date(now));
 const date=new Intl.DateTimeFormat('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Jakarta'}).format(new Date(now));
 return <main className="public-rundown-page"><header className="public-rundown-header"><div><span className="auth-kicker">LIVE EVENT TIMELINE</span><h1>Rundown Acara</h1><p>{event?.title||'Memuat event…'} · Waktu Indonesia Barat (WIB)</p></div><a href="/event" className="public-rundown-home">HEMS</a></header>{loading?<div className="public-rundown-state">Memuat rundown acara…</div>:error?<div className="public-rundown-state"><h2>Rundown tidak tersedia</h2><p>{error}</p></div>:<><div className="rundown-preview-now public-rundown-clock"><span className="rundown-live-dot"/><div><small>WAKTU SEKARANG</small><strong>{clock} WIB</strong></div><span className="rundown-preview-date">{date}</span></div>{agendas.length?<div className="rundown-timeline rundown-preview-timeline public-rundown-timeline">{agendas.map(item=>{const start=new Date(item.starts_at).getTime(),end=new Date(item.ends_at).getTime(),live=start<=now&&end>now,done=now>=end;return <article key={item.id} className={'rundown-timeline-item '+(live?'is-live':done?'is-done':'is-upcoming')}><div className="rundown-timeline-marker"><i/></div><div className="rundown-timeline-content"><div className="rundown-time">{timeText(item.starts_at)} – {timeText(item.ends_at)} {live&&<b>SEDANG BERLANGSUNG</b>}{done&&<small>Selesai</small>}{!live&&!done&&<small className="rundown-upcoming-label">Akan datang</small>}</div><h3>{item.title}</h3>{item.description&&<p>{item.description}</p>}{item.person_in_charge&&<div className="rundown-pic">PIC: {item.person_in_charge}</div>}</div></article>})}</div>:<div className="public-rundown-state">Belum ada agenda untuk event ini.</div>}<footer className="rundown-preview-legend"><span><i className="legend-live"/> Sedang berlangsung</span><span><i className="legend-done"/> Selesai</span><span><i className="legend-upcoming"/> Akan datang</span></footer></>}</main>
}

