 async function loadWhatsAppTemplate(){const{data,error}=await supabase.from('user_settings').select('whatsapp_invitation_template').eq('user_id',user.id).maybeSingle();if(error){setNotice('Pengaturan template tidak dapat dimuat: '+error.message);return}setWhatsappTemplate(data?.whatsapp_invitation_template||defaultWhatsAppTemplate);setTemplateLoaded(true)}
