 useEffect(()=>{let active=true;async function buildSharedCheckinQr(){const event=events.find(item=>item.id===activeEvent);setCheckinSharedQr('');setCheckinSharedUrl('');setCheckinSharedError('');if(!event)return;try{let slug=event.slug;if(!slug){slug=crypto.randomUUID().replaceAll('-','');const{data,error}=await supabase.from('events').update({slug}).eq('id',event.id).select().single();if(error)throw error;if(!active)return;setEvents(items=>items.map(item=>item.id===event.id?data:item))}const url=window.location.origin+'/event/'+slug;const image=await QRCode.toDataURL(url,{width:420,margin:3,errorCorrectionLevel:'H'});if(active){setCheckinSharedQr(image);setCheckinSharedUrl(url)}}catch(error){if(active)setCheckinSharedError(error.message||'QR bersama gagal dibuat')}}buildSharedCheckinQr();return()=>{active=false}},[activeEvent,events]);
