 async function openSharedEventQr(event){setBusy(true);let slug=event.slug;if(!slug){slug=crypto.randomUUID().replaceAll('-','');const{data,error}=await supabase.from('events').update({slug}).eq('id',event.id).select().single();if(error){setNotice('QR event gagal dibuat: '+error.message);setBusy(false);return}setEvents(items=>items.map(item=>item.id===event.id?data:item))}const url=window.location.origin+'/event/'+slug;try{const image=await QRCode.toDataURL(url,{width:520,margin:3,errorCorrectionLevel:'H'});setSharedEventQr({title:event.title,url,image});}catch(e){setNotice('QR event gagal dibuat: '+e.message)}setBusy(false)}
